// Pure classification of Stripe off-session charge failures + "is this saved
// PaymentMethod actually reusable" checks. NO SDK, NO db import — so the unit
// tests (test/stripe-card-reuse.test.ts) and the TEST-mode verification script
// (scripts/verify-card-reuse-testmode.ts) can import it without touching Prisma,
// and lib/stripe-cards.ts stays the single place that MOVES money.
//
// WHY THIS FILE EXISTS (2026-10-01 incident). Renewals charging a saved card
// were failing 14+ times/day with Stripe's
//   "The provided PaymentMethod was previously used with a PaymentIntent without
//    Customer attachment, shared with a connected account without Customer
//    attachment, or was detached from a Customer. It may not be used again. To use
//    a PaymentMethod multiple times, you must attach it to a Customer first."
// That error is `invalid_request_error` with NO `code` (verified in TEST mode,
// see the script above), so `classifyChargeError` fell through to its default —
// `transient` — and the worker retried the same dead card EVERY HOUR, silently
// (transient errors never email), while `suspendDueAt` quietly slid toward the
// capped suspension day. A card like that is PERMANENTLY unusable: Stripe will
// never accept it again, and `paymentMethods.attach` fails with the same text.
// The only fix is a new card from the customer, so the right classification is
// `unavailable` (nothing to retry) with a reason the worker can act on.

export type StripeErrorLike = {
  type?: string;
  rawType?: string;
  code?: string;
  decline_code?: string;
  message?: string;
  payment_intent?: { id?: string; status?: string };
};

export function asStripeError(e: unknown): StripeErrorLike | null {
  if (!e || typeof e !== "object") return null;
  const err = e as StripeErrorLike;
  return err.rawType || err.type?.startsWith("Stripe") ? err : null;
}

/**
 * Why a saved card can no longer be charged at all. Stored on
 * `PaymentCard.unusableReason`, so keep these stable (they are read back by the
 * admin card-health page and the customer-portal banner).
 */
export type UnusableCardReason =
  /** The PaymentMethod id no longer exists at Stripe (detached + purged, customer deleted). */
  | "missing_at_stripe"
  /** Stripe refuses to reuse it: consumed by a guest PaymentIntent, or detached from its Customer. */
  | "not_reusable"
  /** It belongs to a different Stripe Customer than the one on this account. */
  | "wrong_customer";

export type OffSessionResult =
  /** Money captured. `amountCents` is what Stripe actually took, not what we asked for. */
  | { ok: true; paymentIntentId: string; amountCents: number; replayed: boolean }
  /** 3-D Secure or equivalent: the customer must approve it with their bank. */
  | { ok: false; kind: "requires_action"; paymentIntentId: string | null; message: string }
  /** The issuer said no. A real dunning event. */
  | { ok: false; kind: "declined"; message: string; code?: string }
  /** Our side or Stripe's side wobbled. NOT the customer's fault — never dun for it. */
  | { ok: false; kind: "transient"; message: string }
  /**
   * Nothing to charge with (no card, Stripe off, amount under Stripe's floor), OR
   * the saved card is permanently dead at Stripe — `reason` says which, and is
   * present ONLY when the saved PaymentMethod itself is the problem (so the
   * caller knows to retire the card and ask for a new one, rather than retry).
   */
  | { ok: false; kind: "unavailable"; message: string; reason?: UnusableCardReason };

/**
 * Stripe's wording for a PaymentMethod that can never be used again. Matched on
 * MESSAGE because the error carries no `code` (verified 2026-10-01 in TEST mode
 * against stripe-node 22 / API 2026-06-24: `type: StripeInvalidRequestError,
 * rawType: invalid_request_error, code: undefined`). Both the charge attempt and
 * a later `paymentMethods.attach` use this phrasing. Kept deliberately loose
 * (several independent fragments) so a small rewording at Stripe still matches.
 */
const NOT_REUSABLE_RE =
  /(previously used (with a PaymentIntent )?without (being attached to a Customer|Customer attachment)|detached from a Customer|may not be used again|must attach it to a Customer)/i;

/** True when a Stripe error says the PaymentMethod is permanently unusable. */
export function isNotReusableError(e: unknown): boolean {
  const err = asStripeError(e);
  if (!err || err.rawType !== "invalid_request_error") return false;
  return NOT_REUSABLE_RE.test(String(err.message ?? ""));
}

/**
 * Split a charge failure into the cases that deserve different treatment: the
 * bank wants the customer to confirm, the bank said no, the saved card is dead,
 * or nothing about the customer went wrong at all.
 *
 * The default is `transient` on purpose. A misclassified transient error costs us
 * a delayed renewal; a misclassified decline costs a paid-up customer their
 * server. Unknown always resolves to the direction that cannot suspend anyone.
 * The ONE exception carved out here is the permanently-dead PaymentMethod, which
 * is unambiguous (Stripe says "may not be used again") and where "transient"
 * was the harmful classification: an hourly silent retry forever, no email, and
 * a suspension the customer never heard was coming.
 */
/** Every non-success arm of `OffSessionResult` — what a thrown error can ever map to. */
export type OffSessionFailure = Exclude<OffSessionResult, { ok: true }>;

export function classifyChargeError(e: unknown): OffSessionFailure {
  const err = asStripeError(e);
  const message = String(err?.message ?? (e as Error)?.message ?? e).slice(0, 300);
  if (!err) return { ok: false, kind: "transient", message };

  // 3-D Secure surfaces as a card error with this code, with the PI attached.
  if (err.code === "authentication_required" || err.payment_intent?.status === "requires_action") {
    return {
      ok: false,
      kind: "requires_action",
      paymentIntentId: err.payment_intent?.id ?? null,
      message,
    };
  }
  if (err.rawType === "card_error") {
    return { ok: false, kind: "declined", message, code: err.decline_code ?? err.code };
  }
  // The saved method vanished at Stripe (detached elsewhere, customer deleted).
  // Not a decline — there is nothing to retry until a new card is saved.
  if (err.rawType === "invalid_request_error" && err.code === "resource_missing") {
    return { ok: false, kind: "unavailable", message, reason: "missing_at_stripe" };
  }
  // The saved method exists but Stripe will never accept it again (see the file
  // header). Permanent; the customer has to add a card afresh.
  if (isNotReusableError(err)) {
    return { ok: false, kind: "unavailable", message, reason: "not_reusable" };
  }
  return { ok: false, kind: "transient", message };
}

/** The slice of a Stripe PaymentMethod object the reusability check needs. */
export type PaymentMethodLike = { id: string; customer?: string | { id: string } | null };

/**
 * Can this PaymentMethod be charged off-session for THIS customer, as far as the
 * object itself can tell us? Stripe only lets a PaymentMethod be reused when it
 * is attached to a Customer, so `pm.customer` must be exactly the account's
 * Stripe customer. `null` means consumed-as-guest or detached (dead); a
 * different id means it was saved under another customer (ours or not).
 *
 * Returns the reason it is NOT reusable, or null when it is. Pure.
 */
export function paymentMethodUnusableReason(
  pm: PaymentMethodLike,
  customerId: string | null | undefined,
): UnusableCardReason | null {
  const pmCustomer = typeof pm.customer === "string" ? pm.customer : (pm.customer?.id ?? null);
  if (!pmCustomer) return "not_reusable";
  if (!customerId || pmCustomer !== customerId) return "wrong_customer";
  return null;
}

/** Customer-facing wording for each reason — one place, so email, portal and admin agree. */
export function unusableCardReasonLabel(reason: UnusableCardReason | string | null | undefined): string {
  switch (reason) {
    case "missing_at_stripe":
      return "This card no longer exists at our payment processor.";
    case "wrong_customer":
      return "This card is registered to a different billing profile.";
    case "not_reusable":
    default:
      return "This card was saved in a way that can't be charged automatically.";
  }
}
