/**
 * Hard cap on how far a late-starting or error-delayed sequence may push a
 * suspension past its calendar date. `suspendDueAt` waits for a retry we have
 * PROMISED the customer, and a Stripe outage reschedules that promise hourly
 * forever — without this cap "never suspend mid-sequence" would quietly become
 * "never suspend at all".
 */
const SUSPEND_SLIP_CAP_DAYS = 4;
/** Warn about a saved card this many days before it expires. */
const CARD_EXPIRY_WARN_DAYS = 30;
/** Re-nudge about a still-unreplaced expiring/expired card at most this often. */
const CARD_EXPIRY_RENUDGE_DAYS = 60;
/** Ledger description prefix that identifies an automatic wallet top-up. */
const AUTO_RECHARGE_DESC = "Automatic wallet top-up";
/** Mirrors the floor `saveAutoRecharge` enforces on the customer's own input. */
const AUTO_RECHARGE_MIN_CENTS = 500;
/**
 * How long a server stays up, from the moment we DISCOVER its saved card can
 * never be charged again, before it may be suspended — a platform fault
 * (lib/stripe-charge-errors.ts), so the customer gets a full week of
 * "re-add your card" notices (day 0 / 1 / 3 / final) and never a suspension
 * they were not warned about. Stored on `Server.billingGraceUntil`; an admin
 * can push it further from the card-health page.
 */
const PLATFORM_FAULT_GRACE_DAYS = 7;
/** Re-add-card reminder ladder, days AFTER the first notice: day 1, day 3, then the final notice a day before grace ends. */
const CARD_READD_REMINDER_DAYS = [1, 3] as const;

/**
 * Dunning windows, all measured in DAYS PAST EXPIRY.
 *
 * Settings → Billing is the source of truth. Those three fields and the
 * "Auto-suspend overdue accounts" toggle used to be written to the Setting table and
 * read by NOTHING: the worker used env vars that were never set, so an operator who
 * turned suspensions off during an incident saw "Saved." and then watched the sweep
 * knock customer VMs offline ten minutes later.
async function sendCardReaddNotice(
  server: DueServer,
  cardCents: number,
  stage: "first" | "reminder" | "final",
  now: Date,
): Promise<void> {
  const graceUntil = server.billingGraceUntil!;
  const user = server.user;
  const newStage = server.dunningStage + 1;
  // What the customer is told comes from the state we are about to WRITE.
  const nextAt =
    stage === "final"
      ? graceUntil
      : (() => {
          const idx = Math.min(newStage - 1, CARD_READD_REMINDER_DAYS.length - 1);
          const firstNoticeAt = server.dunningNextAt
            ? new Date(server.dunningNextAt.getTime() - CARD_READD_REMINDER_DAYS[Math.max(0, idx - 1)] * DAY)
            : now;
          const scheduled =
            newStage <= CARD_READD_REMINDER_DAYS.length
              ? new Date(firstNoticeAt.getTime() + CARD_READD_REMINDER_DAYS[newStage - 1] * DAY)
              : new Date(graceUntil.getTime() - DAY);
          const floor = new Date(now.getTime() + MIN_RETRY_GAP_MS);
          const at = scheduled > floor ? scheduled : floor;
          // Never schedule past the grace deadline itself.
          return at < graceUntil ? at : graceUntil;
        })();
  await db.server.update({ where: { id: server.id }, data: { dunningStage: newStage, dunningNextAt: nextAt } });
