async function nudgeCardReadd(opts: { server: DueServer; cardCents: number; now: Date }): Promise<void> {
  const { server, cardCents, now } = opts;
  const graceUntil = server.billingGraceUntil!;
  if (server.dunningNextAt && now < server.dunningNextAt) return; // not this rung's turn yet
  const finalAt = new Date(graceUntil.getTime() - DAY);
