    await sendCardReaddNotice(server, cardCents, "first", now);
    return;
  }
  if (rung <= CARD_READD_REMINDER_DAYS.length) {
    // A reminder rung — unless the final notice is already due, in which case
    // skip straight to it rather than stacking two emails on one day.
    if (now >= finalAt) {
      await sendCardReaddNotice(server, cardCents, "final", now);
    } else {
      await sendCardReaddNotice(server, cardCents, "reminder", now);
    }
    return;
  }
  if (rung === CARD_READD_REMINDER_DAYS.length + 1) {
    await sendCardReaddNotice(server, cardCents, "final", now);
    return;
  }
  // Final notice already sent: hold until the grace deadline, nothing more to say.
  await rescheduleAttempt(server, graceUntil);
}

