/** One resumable run: at most `maxPerRun` Stripe calls, sequential, `delayMs` apart. */
export async function runSweep(
  deps: CardHealthDeps,
  opts: { mode: CardHealthMode; maxPerRun: number; delayMs?: number },
): Promise<SweepState | null> {
  if (opts.mode === "off") return null;
  const now = deps.now();
  const prev = await deps.loadState();
  const resuming = !!prev && !prev.complete && prev.mode === opts.mode;
  const st: SweepState = resuming ? { ...prev!, findings: { ...prev!.findings }, errors: [...prev!.errors] } : freshState(opts.mode, now);
  st.lastRunAt = now.toISOString();

  if (!deps.stripeReachable()) {
    st.stripeUnreachable = true;
    st.complete = true;
    st.errors.push("Stripe is not configured/reachable from the worker — nothing checked");
    await deps.saveState(st);
    return st;
  }

  let calls = 0;
  let consecutiveErrors = 0;
  let exhausted = false;
  while (calls < opts.maxPerRun) {
    const batch = await deps.listCandidates(st.cursor, Math.min(25, opts.maxPerRun - calls));
    if (batch.length === 0) { exhausted = true; break; }
    for (const c of batch) {
      if (calls >= opts.maxPerRun) break;
      if (calls > 0 && opts.delayMs) await deps.sleep(opts.delayMs);
      calls++;
      const r = await checkCard(deps, c, opts.mode);
      st.cursor = c.cardId;
      if (r.outcome.kind === "unknown") {
        // Could not tell. Record, retry next cycle, and NEVER touch the card.
        st.unknown++;
        consecutiveErrors++;
        if (st.errors.length < 10) st.errors.push(r.outcome.message.slice(0, 160));
        if (consecutiveErrors >= 5 && st.checked + st.healthy === 0) {
          st.stripeUnreachable = true;
          st.errors.push("5 consecutive Stripe errors with no success — aborting; will retry next tick");
          st.complete = true; // this cycle is spent; tomorrow tries again
          await deps.saveState(st);
          return st;
        }
        continue;
      }
      consecutiveErrors = 0;
      st.checked++;
      if (r.outcome.kind === "healthy") {
        st.healthy++;
      } else {
        st.findings[r.outcome.reason] = (st.findings[r.outcome.reason] ?? 0) + 1;
        if (r.isNew) st.newFindings++;
        if (r.enforced) st.enforced++;
      }
    }
  }
  if (exhausted) st.complete = true;

  // A card that checked healthy but still has an open finding (customer fixed it
  // at Stripe, or an expiry finding after a card update) is closed by the
  // resolve pass below once nothing flags it; healthy-in-this-run is handled here.
  await resolveFindings(deps);

  if (st.complete && !st.alerted && st.newFindings > 0) {
    const open = (await deps.openFindings()).length;
    const parts = Object.entries(st.findings).map(([k, v]) => `${v} ${k}`).join(", ");
    await deps.alertAdmins(
      ALERT_TITLE,
      `Card-health sweep (${st.mode} mode) checked ${st.checked} cards: ${st.newFindings} new finding(s) (${parts}); ${open} open in total. ` +
        (st.mode === "report" ? "Report mode — customers have NOT been contacted." : `${st.enforced} card(s) retired so the re-add ladder starts.`),
    );
    st.alerted = true;
  }
  await deps.saveState(st);
  return st;
}

