// Daily saved-card health check — the PURE core. NO db / Stripe SDK import: every
// side effect goes through the `CardHealthDeps` object, so test/card-health.test.ts
// drives the whole sweep with in-memory fakes, and worker/card-health.ts is the
// only place that wires it to Prisma + Stripe.
//
// WHY (2026-10-05). 8 of 54 saved cards were not attached to their Stripe
// customer; 5 were still marked usable, so nothing warned the customers until a
// renewal failed. This sweep asks Stripe about every usable card BEFORE it is
// due, using the same classifier the renewal path uses
// (`paymentMethodUnusableReason`), and — only in 'enforce' mode — retires the
// dead ones through the EXISTING `markPaymentMethodUnusable`, which is what
// starts the Billing-page banner, the pre-renewal reminder and (at renewal) the
// grace + re-add ladder. This module never emails anyone.
import { paymentMethodUnusableReason, type UnusableCardReason } from "./stripe-charge-errors";

export type CardHealthMode = "off" | "report" | "enforce";
export type FindingReason = UnusableCardReason | "expired" | "expiring_soon";

/** Reasons Stripe itself says are permanent. ONLY these are ever enforced. */
export const HARD_REASONS: readonly FindingReason[] = ["not_reusable", "wrong_customer", "missing_at_stripe"];
export const EXPIRY_WARN_DAYS = 30;
const DAY = 86_400_000;

export function parseMode(v: string | null | undefined): CardHealthMode {
  return v === "report" || v === "enforce" ? v : "off";
}

/** What Stripe said when asked for one PaymentMethod. `error` = could not tell (network, 5xx, rate limit...). */
export type PmFetch =
  | { status: "ok"; pm: { id: string; customer?: string | { id: string } | null; card?: { exp_month?: number | null; exp_year?: number | null } | null } }
  | { status: "missing" }
  | { status: "error"; message: string };

export type Outcome =
  | { kind: "healthy" }
  | { kind: "finding"; reason: FindingReason }
  | { kind: "unknown"; message: string };

/** First instant AFTER the card's last valid day (cards are valid through the end of their expiry month). */
export function cardExpiryEnd(expMonth: number, expYear: number): Date {
  return new Date(Date.UTC(expYear, expMonth, 1));
}

/** Classify one retrieval. Hard Stripe reasons win over expiry; an error is NEVER a finding. */
export function classifyFetch(
  fetched: PmFetch,
  customerId: string | null | undefined,
  now: Date,
  stored?: { expMonth: number | null; expYear: number | null },
): Outcome {
  if (fetched.status === "error") return { kind: "unknown", message: fetched.message };
  if (fetched.status === "missing") return { kind: "finding", reason: "missing_at_stripe" };
  // Without our Stripe customer id we cannot tell "attached to someone else" from
  // "we simply lost our own pointer" — never accuse the card on that basis.
  if (!customerId) return { kind: "unknown", message: "account has no Stripe customer id" };
  const hard = paymentMethodUnusableReason(fetched.pm, customerId);
  if (hard) return { kind: "finding", reason: hard };
  const m = fetched.pm.card?.exp_month ?? stored?.expMonth ?? null;
  const y = fetched.pm.card?.exp_year ?? stored?.expYear ?? null;
  if (m && y) {
    const end = cardExpiryEnd(m, y).getTime();
    if (end <= now.getTime()) return { kind: "finding", reason: "expired" };
    if (end <= now.getTime() + EXPIRY_WARN_DAYS * DAY) return { kind: "finding", reason: "expiring_soon" };
  }
  return { kind: "healthy" };
}

export type Candidate = {
  cardId: string;
  userId: string;
  pmId: string;
  stripeCustomerId: string | null;
  expMonth: number | null;
  expYear: number | null;
};

export type OpenFinding = { id: string; userId: string; paymentCardId: string; reason: string; enforced: boolean };

export type CardHealthDeps = {
  now: () => Date;
  sleep: (ms: number) => Promise<void>;
  stripeReachable: () => boolean;
  /** Usable cards of eligible users, ordered by card id ascending, strictly after `afterId`. */
  listCandidates: (afterId: string | null, take: number) => Promise<Candidate[]>;
  retrievePm: (pmId: string) => Promise<PmFetch>;
  /** Insert or refresh the OPEN finding for this card. Returns true when it is NEW. */
  upsertFinding: (c: Candidate, reason: FindingReason, now: Date) => Promise<boolean>;
  markEnforced: (cardId: string) => Promise<void>;
  openFindings: () => Promise<OpenFinding[]>;
  resolveFinding: (id: string, resolution: string, now: Date) => Promise<void>;
  /** Usable PaymentCard ids this user has right now (unusableAt null). */
  usableCardIds: (userId: string) => Promise<string[]>;
  /** Existing retire path (lib/stripe-cards.ts markPaymentMethodUnusable) — idempotent. */
  markUnusable: (userId: string, pmId: string, reason: UnusableCardReason) => Promise<void>;
  /** Does this finding's card still exist as a row? */
  cardExists: (cardId: string) => Promise<boolean>;
