/**
 * Should a tick start/continue a cycle? A cycle in progress (cursor set, not
 * complete) always continues; a new one starts once per UTC day at/after
 * `quietHourUtc`, or when an admin asked for 'run now' (`runNowAt` newer than the
 * last run).
 */
export function shouldRun(opts: {
  mode: CardHealthMode; state: SweepState | null; now: Date; quietHourUtc: number; runNowAt: string | null;
}): boolean {
  const { mode, state, now } = opts;
  if (mode === "off") return false;
  if (!state) return now.getUTCHours() >= opts.quietHourUtc || !!opts.runNowAt;
  if (!state.complete) return true;
  if (opts.runNowAt && opts.runNowAt > state.lastRunAt) return true;
  const sameDay = state.cycleStartedAt.slice(0, 10) === now.toISOString().slice(0, 10);
  return !sameDay && now.getUTCHours() >= opts.quietHourUtc;
