// Production wiring for lib/card-health.ts: Prisma + Stripe (READ-ONLY
// `paymentMethods.retrieve`, nothing else) + the existing retire path. Shared by
// the worker sweep and the admin "Re-check now" action.
import { db } from "./db";
import { stripe, stripeConfigured } from "./stripe";
import { getSetting, setSetting } from "./settings";
import { asStripeError } from "./stripe-charge-errors";
import { markPaymentMethodUnusable } from "./stripe-cards";
import type { CardHealthDeps, Candidate, PmFetch, SweepState } from "./card-health";

export const STATE_KEY = "card_health_state";
export const RUN_NOW_KEY = "card_health_run_now";

/** Accounts whose renewals can depend on the card: a live server, or wallet auto-recharge on. */
const ELIGIBLE_USER = {
  OR: [{ servers: { some: { status: { not: "DELETING" as const } } } }, { autoRechargeEnabled: true }],
};

export async function retrievePmReadOnly(pmId: string): Promise<PmFetch> {
  try {
    const pm = await stripe().paymentMethods.retrieve(pmId);
    return { status: "ok", pm };
  } catch (e) {
    const err = asStripeError(e);
    if (err?.rawType === "invalid_request_error" && err.code === "resource_missing") return { status: "missing" };
    // Everything else — network, 5xx, rate limit, auth — is "could not tell", never a verdict.
    return { status: "error", message: String(err?.message ?? (e as Error)?.message ?? e).slice(0, 200) };
  }
}

export function liveDeps(alertAdmins: (title: string, body: string) => Promise<void>): CardHealthDeps {
  return {
    now: () => new Date(),
    sleep: (ms) => new Promise((r) => setTimeout(r, ms)),
    stripeReachable: () => stripeConfigured(),
    listCandidates: async (afterId, take) => {
      const rows = await db.paymentCard.findMany({
        where: { unusableAt: null, user: ELIGIBLE_USER, ...(afterId ? { id: { gt: afterId } } : {}) },
        orderBy: { id: "asc" },
        take,
        select: { id: true, userId: true, stripePaymentMethodId: true, expMonth: true, expYear: true, user: { select: { stripeCustomerId: true } } },
      });
      return rows.map((r): Candidate => ({
        cardId: r.id, userId: r.userId, pmId: r.stripePaymentMethodId, stripeCustomerId: r.user.stripeCustomerId,
        expMonth: r.expMonth, expYear: r.expYear,
      }));
    },
    retrievePm: retrievePmReadOnly,
    upsertFinding: async (c, reason, now) => {
      const open = await db.cardHealthFinding.findFirst({ where: { paymentCardId: c.cardId, resolvedAt: null } });
      if (open) {
        await db.cardHealthFinding.update({ where: { id: open.id }, data: { lastSeenAt: now, reason } });
        return false;
      }
      await db.cardHealthFinding.create({ data: { userId: c.userId, paymentCardId: c.cardId, reason, firstSeenAt: now, lastSeenAt: now } });
      return true;
    },
    markEnforced: async (cardId) => {
      await db.cardHealthFinding.updateMany({ where: { paymentCardId: cardId, resolvedAt: null }, data: { enforced: true } });
    },
    resolveCardFinding: async (cardId, resolution, now) => {
      await db.cardHealthFinding.updateMany({ where: { paymentCardId: cardId, resolvedAt: null }, data: { resolvedAt: now, resolution } });
    },
    openFindings: async () =>
      db.cardHealthFinding.findMany({
        where: { resolvedAt: null },
        select: { id: true, userId: true, paymentCardId: true, reason: true, enforced: true },
      }),
    resolveFinding: async (id, resolution, now) => {
      await db.cardHealthFinding.update({ where: { id }, data: { resolvedAt: now, resolution } });
    },
    usableCardIds: async (userId) =>
      (await db.paymentCard.findMany({ where: { userId, unusableAt: null }, select: { id: true } })).map((c) => c.id),
    cardExists: async (cardId) => !!(await db.paymentCard.findUnique({ where: { id: cardId }, select: { id: true } })),
    markUnusable: markPaymentMethodUnusable,
    loadState: async () => {
      try {
        const raw = await getSetting(STATE_KEY, "");
        return raw ? (JSON.parse(raw) as SweepState) : null;
      } catch { return null; }
    },
    saveState: (s) => setSetting(STATE_KEY, JSON.stringify(s)),
    alertAdmins,
  };
}
