/* ---- Saved-card health sweep (worker/card-health.ts, lib/card-health.ts) ---- */

/** Set the sweep mode. ADMIN-only: 'enforce' causes customer-visible re-add notices. */
export async function adminSetCardHealthMode(mode: string): Promise<{ ok?: true; error?: string; message?: string }> {
  const admin = await requireAdmin();
  if (mode !== "off" && mode !== "report" && mode !== "enforce") return { error: "Unknown mode." };
  const { getSetting, setSetting } = await import("@/lib/settings");
  const before = await getSetting("card_health_sweep_mode", "off");
  await setSetting("card_health_sweep_mode", mode);
  await audit(admin.id, "billing.card_health_mode", `${before} -> ${mode}`);
  revalidatePath("/admin/billing/card-health");
  return { ok: true, message: `Card-health sweep mode is now ${mode}.` };
}

/** Ask the worker for an immediate sweep cycle (it picks the flag up within ~10 min). */
export async function adminRunCardHealthNow(): Promise<{ ok?: true; error?: string; message?: string }> {
  const admin = await requireArea("billing");
  const { getSetting, setSetting } = await import("@/lib/settings");
  const { RUN_NOW_KEY } = await import("@/lib/card-health-live");
  if ((await getSetting("card_health_sweep_mode", "off")) === "off") return { error: "The sweep is off. Set it to report first." };
  await setSetting(RUN_NOW_KEY, new Date().toISOString());
  await audit(admin.id, "billing.card_health_run_now", "requested");
  revalidatePath("/admin/billing/card-health");
  return { ok: true, message: "Queued — the worker starts it within ~10 minutes." };
}

/** Re-check ONE finding's card against Stripe now (read-only call; applies the current mode). */
export async function adminRecheckCardFinding(findingId: string): Promise<{ ok?: true; error?: string; message?: string }> {
  const admin = await requireArea("billing");
  const f = await db.cardHealthFinding.findUnique({ where: { id: findingId } });
  if (!f || f.resolvedAt) return { error: "Finding not found or already resolved." };
  const card = await db.paymentCard.findUnique({
    where: { id: f.paymentCardId },
    select: { id: true, userId: true, stripePaymentMethodId: true, expMonth: true, expYear: true, unusableAt: true, user: { select: { stripeCustomerId: true } } },
  });
  if (!card) {
    await db.cardHealthFinding.update({ where: { id: f.id }, data: { resolvedAt: new Date(), resolution: "card_removed" } });
    revalidatePath("/admin/billing/card-health");
    return { ok: true, message: "Card no longer exists — finding closed." };
  }
  const [{ liveDeps }, { checkCard, parseMode, resolveFindings }, { getSetting }] = await Promise.all([
    import("@/lib/card-health-live"), import("@/lib/card-health"), import("@/lib/settings"),
  ]);
  if (!stripeConfigured()) return { error: "Stripe is not configured." };
  const deps = liveDeps(async () => {});
  // An already-retired card (enforce ran) is re-read but never re-marked: report semantics.
  const mode = card.unusableAt ? "report" : parseMode(await getSetting("card_health_sweep_mode", "off"));
  const r = await checkCard(deps, {
    cardId: card.id, userId: card.userId, pmId: card.stripePaymentMethodId, stripeCustomerId: card.user.stripeCustomerId,
    expMonth: card.expMonth, expYear: card.expYear,
  }, mode === "off" ? "report" : mode);
  await resolveFindings(deps);
  await audit(admin.id, "billing.card_health_recheck", `${f.id}: ${r.outcome.kind}${r.outcome.kind === "finding" ? ` (${r.outcome.reason})` : ""}`);
  revalidatePath("/admin/billing/card-health");
  return {
    ok: true,
    message: r.outcome.kind === "healthy" ? "Healthy at Stripe — finding closed." : r.outcome.kind === "finding" ? `Still a finding: ${r.outcome.reason}.` : `Could not tell (${r.outcome.message}) — nothing changed.`,
  };
}
