export function RecheckFindingButton({ findingId }: { findingId: string }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  return (
    <div className="flex flex-col items-start gap-1">
      <button
        type="button"
        className="btn-secondary py-1 text-xs"
        disabled={pending}
        onClick={() => start(async () => {
          const res = await adminRecheckCardFinding(findingId);
          setMsg(res.ok ? { ok: true, text: res.message ?? "Done." } : { ok: false, text: res.error ?? "Failed." });
        })}
      >
        {pending ? "Checking…" : "Re-check now"}
      </button>
      {msg && <span className={"text-[11px] " + (msg.ok ? "text-emerald-400" : "text-red-400")}>{msg.text}</span>}
    </div>
  );
}

/** Mode selector + "Run sweep now" for the saved-card health sweep. */
export function SweepControls({ mode }: { mode: string }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [pick, setPick] = useState(mode);
  const show = (res: { ok?: true; error?: string; message?: string }) =>
    setMsg(res.ok ? { ok: true, text: res.message ?? "Done." } : { ok: false, text: res.error ?? "Failed." });
  return (
    <div className="flex flex-wrap items-center gap-2">
      <select className="input py-1 text-xs" value={pick} onChange={(e) => setPick(e.target.value)} aria-label="Sweep mode">
        <option value="off">off</option>
        <option value="report">report (record only)</option>
        <option value="enforce">enforce (retire dead cards, starts the re-add ladder)</option>
      </select>
      <button
        type="button"
        className="btn-secondary py-1 text-xs"
        disabled={pending || pick === mode}
        onClick={() => {
          if (pick === "enforce" && !window.confirm("Enforce mode retires dead saved cards, which starts customer-visible re-add notices. Continue?")) return;
          start(async () => show(await adminSetCardHealthMode(pick)));
        }}
      >
        Save mode
      </button>
      <button type="button" className="btn-secondary py-1 text-xs" disabled={pending || mode === "off"} onClick={() => start(async () => show(await adminRunCardHealthNow()))}>
        Run sweep now
      </button>
      {msg && <span className={"text-[11px] " + (msg.ok ? "text-emerald-400" : "text-red-400")}>{msg.text}</span>}
    </div>
  );
}
