cd /tank/nxeon-wt-cardhealth && cat > test/card-health.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { stripComments } from "./_source-tools.ts";
import {
  checkCard, classifyFetch, parseMode, resolveFindings, runSweep, shouldRun,
  type CardHealthDeps, type Candidate, type PmFetch, type SweepState,
} from "../lib/card-health.ts";

/**
 * Daily saved-card health sweep (lib/card-health.ts). The whole sweep runs against
 * an in-memory fake world — no Prisma, no Stripe — covering classification, the
 * "network error never marks a card dead" rule, report vs enforce, idempotency,
 * the only-card safety, resolve-on-readd, and the per-run cap + resume.
 */

const NOW = new Date("2026-10-05T03:00:00Z");
const ok = (cust: string | null, exp = { exp_month: 12, exp_year: 2030 }): PmFetch => ({ status: "ok", pm: { id: "pm", customer: cust, card: exp } });

type World = {
  cards: { id: string; userId: string; pmId: string; usable: boolean; exp?: [number, number] }[];
  customers: Record<string, string | null>;
  /** pmId -> fetch result, or a function for flapping */
  stripe: Record<string, PmFetch | (() => PmFetch)>;
};

function fake(w: World, opts: { reachable?: boolean } = {}) {
  const findings: any[] = [];
  const marked: string[] = [];
  const alerts: string[] = [];
  const retrieved: string[] = [];
  let state: SweepState | null = null;
  let fid = 0;
  const deps: CardHealthDeps = {
    now: () => NOW,
    sleep: async () => {},
    stripeReachable: () => opts.reachable ?? true,
    listCandidates: async (after, take) =>
      w.cards.filter((c) => c.usable && (!after || c.id > after)).sort((a, b) => (a.id < b.id ? -1 : 1)).slice(0, take)
        .map((c): Candidate => ({ cardId: c.id, userId: c.userId, pmId: c.pmId, stripeCustomerId: w.customers[c.userId] ?? null, expMonth: c.exp?.[0] ?? null, expYear: c.exp?.[1] ?? null })),
    retrievePm: async (id) => {
      retrieved.push(id);
      const r = w.stripe[id];
      const v = typeof r === "function" ? r() : r;
      if (!v) return { status: "missing" };
      return v.status === "ok" ? { status: "ok", pm: { ...v.pm, id } } : v;
    },
    upsertFinding: async (c, reason, now) => {
      const open = findings.find((f) => f.paymentCardId === c.cardId && !f.resolvedAt);
      if (open) { open.reason = reason; open.lastSeenAt = now; return false; }
      findings.push({ id: `f${fid++}`, userId: c.userId, paymentCardId: c.cardId, reason, enforced: false, resolvedAt: null });
      return true;
    },
    markEnforced: async (cardId) => { findings.filter((f) => f.paymentCardId === cardId && !f.resolvedAt).forEach((f) => (f.enforced = true)); },
    resolveCardFinding: async (cardId, resolution) => { findings.filter((f) => f.paymentCardId === cardId && !f.resolvedAt).forEach((f) => { f.resolvedAt = NOW; f.resolution = resolution; }); },
    openFindings: async () => findings.filter((f) => !f.resolvedAt),
    resolveFinding: async (id, resolution) => { const f = findings.find((x) => x.id === id)!; f.resolvedAt = NOW; f.resolution = resolution; },
    usableCardIds: async (u) => w.cards.filter((c) => c.userId === u && c.usable).map((c) => c.id),
    cardExists: async (id) => w.cards.some((c) => c.id === id),
    // Like markPaymentMethodUnusable: idempotent, flips the row.
    markUnusable: async (_u, pmId) => { marked.push(pmId); const c = w.cards.find((x) => x.pmId === pmId); if (c) c.usable = false; },
    loadState: async () => (state ? structuredClone(state) : null),
    saveState: async (s) => { state = structuredClone(s); },
    alertAdmins: async (t, b) => { alerts.push(`${t}|${b}`); },
  };
  return { deps, findings, marked, alerts, retrieved, getState: () => state };
}

const base = (): World => ({
  cards: [{ id: "c1", userId: "u1", pmId: "pm1", usable: true }],
  customers: { u1: "cus_1" },
  stripe: { pm1: ok("cus_1") },
});

test("classification: every reason", () => {
  assert.deepEqual(classifyFetch(ok("cus_1"), "cus_1", NOW), { kind: "healthy" });
