  const findings: any[] = [];
  const marked: string[] = [];
  const alerts: string[] = [];
  const retrieved: string[] = [];
  let state: SweepState | null = null;
  let fid = 0;
  const deps: CardHealthDeps = {
    now: () => NOW,
    sleep: async () => {},
    stripeReachable: () => opts.reachable ?? true,
    listCandidates: async (after, take) =>
