    openFindings: async () => findings.filter((f) => !f.resolvedAt),
    resolveFinding: async (id, resolution) => { const f = findings.find((x) => x.id === id)!; f.resolvedAt = NOW; f.resolution = resolution; },
    usableCardIds: async (u) => w.cards.filter((c) => c.userId === u && c.usable).map((c) => c.id),
    cardExists: async (id) => w.cards.some((c) => c.id === id),
