  w.cards.push({ id: "c9", userId: "u1", pmId: "pm9", usable: true }); // customer re-adds
  assert.equal(await resolveFindings(f.deps), 1);
  assert.equal(f.findings[0].resolution, "healthy_card_on_file");
});

test("resolve-on-readd: another FLAGGED card does not count as healthy", async () => {
  const w = base(); w.stripe.pm1 = ok(null);
  w.cards.push({ id: "c2", userId: "u1", pmId: "pm2", usable: true }); w.stripe.pm2 = ok(null);
  const f = fake(w);
  await runSweep(f.deps, { mode: "report", maxPerRun: 10 });
