  assert.equal(await resolveFindings(f.deps), 0);
});

test("a removed card closes its finding", async () => {
  const w = base(); w.stripe.pm1 = ok(null);
  const f = fake(w);
  await runSweep(f.deps, { mode: "report", maxPerRun: 10 });
