});

test("per-run cap and resume: no card is checked twice or skipped; one alert at completion", async () => {
  const w: World = { cards: [], customers: {}, stripe: {} };
  for (let i = 0; i < 7; i++) {
    w.cards.push({ id: `c${i}`, userId: `u${i}`, pmId: `pm${i}`, usable: true });
    w.customers[`u${i}`] = `cus${i}`;
    w.stripe[`pm${i}`] = ok(i % 2 ? null : `cus${i}`);
  }
  const f = fake(w);
  let st = await runSweep(f.deps, { mode: "report", maxPerRun: 3 });
  assert.equal(st!.complete, false);
  assert.equal(f.retrieved.length, 3);
  assert.equal(f.alerts.length, 0);
  st = await runSweep(f.deps, { mode: "report", maxPerRun: 3 });
  assert.equal(st!.complete, false);
  st = await runSweep(f.deps, { mode: "report", maxPerRun: 3 });
  assert.equal(st!.complete, true);
  assert.deepEqual([...new Set(f.retrieved)].length, 7);
  assert.equal(f.retrieved.length, 7);
  assert.equal(st!.healthy, 4);
  assert.equal(st!.findings.not_reusable, 3);
  assert.equal(f.alerts.length, 1);
});

test("shouldRun: off never; mid-cycle continues; once per UTC day after the quiet hour; run-now wins", () => {
  const done = (day: string): SweepState => ({ cycleStartedAt: `${day}T03:00:00Z`, lastRunAt: `${day}T03:05:00Z`, mode: "report", cursor: null, complete: true, checked: 1, healthy: 1, unknown: 0, skipped: 0, newFindings: 0, enforced: 0, findings: {}, errors: [], stripeUnreachable: false, alerted: false });
  const at = (iso: string) => new Date(iso);
  assert.equal(shouldRun({ mode: "off", state: null, now: NOW, quietHourUtc: 3, runNowAt: null }), false);
  assert.equal(shouldRun({ mode: "report", state: { ...done("2026-10-05"), complete: false, cursor: "c3" }, now: NOW, quietHourUtc: 3, runNowAt: null }), true);
  assert.equal(shouldRun({ mode: "report", state: done("2026-10-05"), now: at("2026-10-05T15:00:00Z"), quietHourUtc: 3, runNowAt: null }), false);
  assert.equal(shouldRun({ mode: "report", state: done("2026-10-04"), now: at("2026-10-05T01:00:00Z"), quietHourUtc: 3, runNowAt: null }), false);
  assert.equal(shouldRun({ mode: "report", state: done("2026-10-04"), now: at("2026-10-05T03:10:00Z"), quietHourUtc: 3, runNowAt: null }), true);
  assert.equal(shouldRun({ mode: "report", state: done("2026-10-05"), now: at("2026-10-05T15:00:00Z"), quietHourUtc: 3, runNowAt: "2026-10-05T14:00:00Z" }), true);
});

