const read = (p: string) => stripComments(readFileSync(new URL(`../${p}`, import.meta.url), "utf8"));

test("the sweep never emails customers and only uses the read-only Stripe retrieve", () => {
  for (const p of ["lib/card-health.ts", "lib/card-health-live.ts", "worker/card-health.ts"]) {
    const src = read(p);
    assert.doesNotMatch(src, /\bmail\(|sendMail|emails\.|notify\(/, p);
    assert.doesNotMatch(src, /\.(create|update|del|detach|attach|confirm)\(/.source.length ? /stripe\(\)\.\w+\.(create|update|del|detach|attach|confirm)\(/ : /x^/, p);
  }
  assert.match(read("lib/card-health-live.ts"), /markPaymentMethodUnusable/);
});

test("the existing ladder stays idempotent (enforce cannot double-send): grace + reminder markers present", () => {
  const b = read("worker/billing.ts");
  assert.match(b, /alreadyInGrace/);
  assert.match(b, /if \(!alreadyInGrace\) await sendCardReaddNotice/);
  assert.match(b, /renewalReminderSentAt: null/);
  const c = read("lib/stripe-cards.ts");
  assert.match(c, /unusableAt: row\.unusableAt \?\? new Date\(\)/);
});

test("worker registers the sweep once and it defaults OFF", () => {
